import { test, expect } from '@playwright/test';

test.describe('Table Sorting by Column Headers', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should sort table by clicking column headers and display sorted data', async ({ page }) => {
    // Verify initial table is displayed
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are visible and clickable
    const headers = page.getByRole('columnheader');
    await expect(headers).toBeVisible();

    // Verify first column header is visible and clickable
    const firstHeader = page.getByRole('columnheader', { name: /name/i });
    await expect(firstHeader).toBeVisible();
    await expect(firstHeader).toBeClickable();

    // Verify second column header is visible and clickable
    const secondHeader = page.getByRole('columnheader', { name: /age/i });
    await expect(secondHeader).toBeVisible();
    await expect(secondHeader).toBeClickable();

    // Verify third column header is visible and clickable
    const thirdHeader = page.getByRole('columnheader', { name: /email/i });
    await expect(thirdHeader).toBeVisible();
    await expect(thirdHeader).toBeClickable();

    // Verify table data is displayed
    const rows = page.getByRole('row');
    await expect(rows).toHaveCount(10);

    // Click first column header to sort by name
    await firstHeader.click();

    // Verify table is now sorted by name
    const sortedRows = page.getByRole('row');
    await expect(sortedRows).toHaveCount(10);
    const firstRow = sortedRows.nth(0);
    await expect(firstRow).toContainText('Alice');
    const lastRow = sortedRows.nth(-1);
    await expect(lastRow).toContainText('Zoe');

    // Click second column header to sort by age
    await secondHeader.click();

    // Verify table is now sorted by age
    const ageSortedRows = page.getByRole('row');
    await expect(ageSortedRows).toHaveCount(10);
    const firstAgeRow = ageSortedRows.nth(0);
    await expect(firstAgeRow).toContainText('Bob');
    const lastAgeRow = ageSortedRows.nth(-1);
    await expect(lastAgeRow).toContainText('Charlie');

    // Click third column header to sort by email
    await thirdHeader.click();

    // Verify table is now sorted by email
    const emailSortedRows = page.getByRole('row');
    await expect(emailSortedRows).toHaveCount(10);
    const firstEmailRow = emailSortedRows.nth(0);
    await expect(firstEmailRow).toContainText('alice@example.com');
    const lastEmailRow = emailSortedRows.nth(-1);
    await expect(lastEmailRow).toContainText('charlie@example.com');
  });

